"""Shelves: stock levels, history, and shipped quantities for orders."""

from .model import unlimited


def sorted_movements(movements):
    """Date order; movements on the same day keep their order (stable sort)."""
    return sorted(movements, key=lambda m: m.date)


def first_below_zero(movements):
    """The first movement (in counting order) that takes any SKU below zero."""
    running = {}
    for m in sorted_movements(movements):
        running[m.sku] = running.get(m.sku, 0) + m.quantity
        if running[m.sku] < 0:
            return m
    return None


def stock_levels(catalog, movements):
    """SKU -> quantity on the shelf, for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        if m.sku in levels:
            levels[m.sku] += m.quantity
    return levels


def history(movements, sku):
    """[(movement, balance after it)] for one SKU, in counting order."""
    balance = 0
    rows = []
    for m in sorted_movements(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append((m, balance))
    return rows


def status_of(onhand, reorder):
    if onhand == 0:
        return "out"
    return "low" if onhand <= reorder else "ok"


def shipped_index(movements):
    """(note, sku) -> units sent out under that note."""
    index = {}
    for m in movements:
        if m.quantity < 0:
            key = (m.note, m.sku)
            index[key] = index.get(key, 0) - m.quantity
    return index


def order_rows(order, index):
    """[(sku, ordered, shipped)] per order line; shipped is capped at ordered."""
    note = "order " + order.id
    return [(sku, qty, min(qty, index.get((note, sku), 0))) for sku, qty in order.lines]


def order_status(rows):
    if all(shipped >= qty for _, qty, shipped in rows):
        return "complete"
    if all(shipped == 0 for _, _, shipped in rows):
        return "open"
    return "partial"


def available_to_ship(movements, sku, date):
    """Most that can leave on ``date`` without any later movement going below zero."""
    running = 0
    at_date = 0
    later_floor = None
    for m in sorted_movements(movements):
        if m.sku != sku:
            continue
        running += m.quantity
        if m.date <= date:
            at_date = running
        elif later_floor is None or running < later_floor:
            later_floor = running
    return at_date if later_floor is None else min(at_date, later_floor)


stock_levels = unlimited(stock_levels)

