                        "quantity": l.quantity,
                        "unit": _amount(l.unit),
                        "gross": _amount(l.gross),
                        "discount": _amount(l.discount),
                        "net": _amount(l.net),
                    }
                    for l in quote.lines
                ],
                "subtotal": _amount(quote.subtotal),
                "order_discount": _amount(quote.order_discount),
                "tax": _amount(quote.tax),
                "total": _amount(quote.total),
            }
        )
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (l.sku, l.quantity, _amount(l.unit), _amount(l.gross), _amount(l.discount), _amount(l.net))
        )
    out.append("subtotal " + _amount(quote.subtotal))
    out.append("order discount " + _amount(quote.order_discount))
    out.append("tax " + _amount(quote.tax))
    out.append("total " + _amount(quote.total))
    return "\n".join(out) + "\n"


def _invoice_quote(order, rows, catalog):
    shipped = [(sku, done) for sku, _, done in rows if done > 0]
    if not shipped:
        return None
    return price_order(SimpleNamespace(lines=shipped), catalog)


def _stock(c):
    levels = stock_levels(c.catalog, c.moves)
    rows = [
        (p.sku, p.name, levels[p.sku], status_of(levels[p.sku], p.reorder))
        for p in (c.catalog[s] for s in sorted(c.catalog))
    ]
