        return _dump([{"sku": s, "name": n, "onhand": q, "status": t} for s, n, q, t in rows])
    return "".join("%s %d %s %s\n" % row for row in rows)


def _low(c):
    levels = stock_levels(c.catalog, c.moves)
    rows = []
    for sku in sorted(c.catalog):
        p = c.catalog[sku]
        if status_of(levels[sku], p.reorder) != "ok":
            rows.append((sku, levels[sku], p.reorder, max(1, 2 * p.reorder - levels[sku])))
