    parts = c.moves_text.split("\n")
    line = len(parts) if c.moves_text.endswith("\n") else len(parts) + 1
    candidate = Movement(parse_date(date_text), sku, quantity, note, line)
    bad = first_below_zero(c.moves + [candidate])
    if bad is not None:
        where = "this movement" if bad is candidate else "the movement on line %d" % bad.line
        raise Failure("refused: stock of %s would go below zero at %s" % (bad.sku, where))
