            )
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n"
        % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


HANDLERS = {
    "stock": _stock,
    "low": _low,
    "history": _history,
    "receive": _movement,
    "ship": _movement,
    "quote": _quote,
    "fulfil": _fulfil,
    "invoice": _invoice,
    "report": _report,
}


def run(command, positionals, options):
    """Read and parse the files the command needs, carry it out, return its output."""
    directory = options.get("dir", ".")
    if not os.path.isdir(directory):
        raise InputError("%s: not a folder that can be read" % directory)
    needed = FILES[command]
    raw = {name: _read(directory, name, name == "catalog") for name in needed}
    catalog = _parse("catalog.txt", parse_catalog, raw["catalog"][1])
    c = SimpleNamespace(
        command=command,
        positionals=positionals,
        options=options,
        directory=directory,
        catalog=catalog,
        moves=[],
        moves_data=b"",
        moves_text="",
        orders=[],
    )
    if "movements" in raw:
        c.moves_data, c.moves_text = raw["movements"]
        c.moves = _parse("movements.txt", parse_movements, c.moves_text, catalog)
    if "orders" in raw:
        c.orders = _parse("orders.txt", parse_orders, raw["orders"][1], catalog)
    return HANDLERS[command](c)


def _write_stderr(message):
    stream = sys.stderr
    try:
        stream.write(message + "\n")
    except UnicodeEncodeError:
        stream.write(message.encode("utf-8", "backslashreplace").decode("ascii", "replace") + "\n")
    try:
        stream.flush()
    except (OSError, ValueError):
        pass


def _silence_stdout():
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    stream = sys.stdout
    try:
        buffer = getattr(stream, "buffer", None)
        if buffer is not None:
            stream.flush()
            buffer.write(text.encode("utf-8"))
            buffer.flush()
        else:
            stream.write(text)
            stream.flush()
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _silence_stdout()
        _write_stderr("stockroom: cannot write output (%s)" % (exc.strerror or exc))
        return 2
    return 0


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    with unlimited_digits():
        try:
            command, positionals, options = parse_args(args)
            text = run(command, positionals, options)
        except UsageError as exc:
            _write_stderr("stockroom: %s\n%s" % (exc, USAGE))
            return 2
        except InputError as exc:
            _write_stderr("stockroom: %s" % exc)
            return 2
        except Failure as exc:
            _write_stderr("stockroom: %s" % exc)
            return 1
        return _emit(text)

