"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import re
import sys
from types import SimpleNamespace

from .ledger import (
    available_to_ship,
    first_below_zero,
    history,
    order_rows,
    order_status,
    shipped_index,
    status_of,
    stock_levels,
)
from .model import Movement, ParseError, ascii_upper, unlimited_digits
from .parsing import parse_catalog, parse_date, parse_movements, parse_orders
from .pricing import price_order

USAGE = """usage: stockroom [--dir DIR] COMMAND ...
  stock [--json]                      what is on the shelves
  low [--json]                        what needs buying
  history SKU [--json]                movements of one product
  receive DATE SKU QUANTITY [NOTE]    add stock-in movement
  ship DATE SKU QUANTITY [NOTE]       add stock-out movement
  quote ORDER [--json]                price an order
  fulfil ORDER DATE                   ship what the shelves cover
  invoice ORDER [--json]              price what has shipped
  report [--format text|csv|json]     one row per order"""

# command -> (min positionals, max positionals, options it takes)
COMMANDS = {
    "stock": (0, 0, ("--json",)),
    "low": (0, 0, ("--json",)),
    "history": (1, 1, ("--json",)),
    "receive": (3, 4, ()),
    "ship": (3, 4, ()),
    "quote": (1, 1, ("--json",)),
    "fulfil": (2, 2, ()),
    "invoice": (1, 1, ("--json",)),
    "report": (0, 0, ("--format",)),
}
RAW = ("receive", "ship", "fulfil")  # every argument but --dir is taken as typed
FILES = {
    "stock": ("catalog", "movements"),
    "low": ("catalog", "movements"),
    "history": ("catalog", "movements"),
    "receive": ("catalog", "movements"),
    "ship": ("catalog", "movements"),
    "quote": ("catalog", "orders"),
    "fulfil": ("catalog", "movements", "orders"),
    "invoice": ("catalog", "movements", "orders"),
    "report": ("catalog", "movements", "orders"),
}
FORMATS = ("text", "csv", "json")
_UINT = re.compile(r"[0-9]+")


class UsageError(Exception):  # exit 2: the command line is wrong
    pass


class InputError(Exception):  # exit 2: a file or folder cannot be read
    pass


class Failure(Exception):  # exit 1: a file mistake or a refused request
    pass


def parse_args(args):
    """Return ``(command, positionals, options)`` or raise UsageError."""
    n = len(args)
    command_at = None
    i = 0
    while i < n:
        arg = args[i]
        if arg in ("--dir", "--format"):
            i += 2
        elif arg.startswith("-") and arg != "-":
            i += 1
        else:
            command_at = i
            break
    if command_at is None:
        raise UsageError("no command given")
    command = args[command_at]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    low, high, allowed = COMMANDS[command]
    options = {}
    positionals = []
    i = 0
    while i < n:
        arg = args[i]
        i += 1
        if i - 1 == command_at:
            continue
        before = i - 1 < command_at
        if arg in ("--dir", "--format") and (arg == "--dir" or before or command not in RAW):
            if i >= n:
                raise UsageError("option %s needs a value" % arg)
            value = args[i]
            i += 1
        elif arg.startswith("--dir=") or (
            arg.startswith("--format=") and (before or command not in RAW)
        ):
            arg, value = arg.split("=", 1)
        elif arg == "--json" and "--json" in allowed:
            options["json"] = True
            continue
        elif arg.startswith("-") and arg != "-" and (before or command not in RAW):
            raise UsageError("unknown option %r for %s" % (arg, command))
        else:
            positionals.append(arg)
            continue
        if arg == "--dir":
            if not value:
                raise UsageError("option --dir needs a folder name")
            options["dir"] = value
        elif "--format" not in allowed:
            raise UsageError("unknown option %r for %s" % (arg, command))
        elif value not in FORMATS:
            raise UsageError("bad --format value %r (text, csv or json)" % value)
        else:
            options["format"] = value
    if not low <= len(positionals) <= high:
        raise UsageError("wrong number of arguments for %s" % command)
    for position in (0,) if command in ("receive", "ship") else (1,) if command == "fulfil" else ():
        if parse_date(positionals[position]) is None:
            raise UsageError("bad date %r (YYYY-MM-DD)" % positionals[position])
    return command, positionals, options


def _read(directory, name, required):
    filename = name + ".txt"
    try:
        with open(os.path.join(directory, filename), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise InputError("%s: not found in %s" % (filename, directory))
        data = b""
    except OSError as exc:
        raise InputError("%s: cannot be read (%s)" % (filename, exc.strerror or exc))
    try:
        return data, data.decode("utf-8")
    except UnicodeDecodeError:
        raise InputError("%s: not valid UTF-8" % filename)


def _parse(filename, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        raise Failure("%s: %s" % (filename, exc))


def _dump(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _amount(value):
    return format(value, "f")


def _move_text(m, balance=None):
    sign = "+" if m.quantity > 0 else "-"
    text = "%s %s %s%d" % (m.date.isoformat(), m.sku, sign, abs(m.quantity))
    return text + (" " + m.note if m.note else "")


def _append(directory, data, movements):
    prefix = b"\n" if data and not data.endswith(b"\n") else b""
    payload = prefix + "".join(_move_text(m) + "\n" for m in movements).encode("utf-8")
    try:
        with open(os.path.join(directory, "movements.txt"), "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise InputError("movements.txt: cannot be written (%s)" % (exc.strerror or exc))


def _find_order(orders, name):
    wanted = ascii_upper(name)
    for order in orders:
        if order.id == wanted:
            return order
    raise Failure("unknown order %s" % wanted)


def _render_quote(order, quote, prefix, as_json):
    if as_json:
        return _dump(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "lines": [
                    {
                        "sku": l.sku,
                        "quantity": l.quantity,
                        "unit": _amount(l.unit),
                        "gross": _amount(l.gross),
                        "discount": _amount(l.discount),
                        "net": _amount(l.net),
                    }
                    for l in quote.lines
                ],
                "subtotal": _amount(quote.subtotal),
                "order_discount": _amount(quote.order_discount),
                "tax": _amount(quote.tax),
                "total": _amount(quote.total),
            }
        )
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (l.sku, l.quantity, _amount(l.unit), _amount(l.gross), _amount(l.discount), _amount(l.net))
        )
    out.append("subtotal " + _amount(quote.subtotal))
    out.append("order discount " + _amount(quote.order_discount))
    out.append("tax " + _amount(quote.tax))
    out.append("total " + _amount(quote.total))
    return "\n".join(out) + "\n"


def _invoice_quote(order, rows, catalog):
    shipped = [(sku, done) for sku, _, done in rows if done > 0]
    if not shipped:
        return None
    return price_order(SimpleNamespace(lines=shipped), catalog)


def _stock(c):
    levels = stock_levels(c.catalog, c.moves)
    rows = [
        (p.sku, p.name, levels[p.sku], status_of(levels[p.sku], p.reorder))
        for p in (c.catalog[s] for s in sorted(c.catalog))
    ]
    if c.options.get("json"):
        return _dump([{"sku": s, "name": n, "onhand": q, "status": t} for s, n, q, t in rows])
    return "".join("%s %d %s %s\n" % row for row in rows)


def _low(c):
    levels = stock_levels(c.catalog, c.moves)
    rows = []
    for sku in sorted(c.catalog):
        p = c.catalog[sku]
        if status_of(levels[sku], p.reorder) != "ok":
            rows.append((sku, levels[sku], p.reorder, max(1, 2 * p.reorder - levels[sku])))
    if c.options.get("json"):
        return _dump(
            [{"sku": s, "onhand": q, "reorder": r, "buy": b} for s, q, r, b in rows]
        )
    return "".join("%s %d %d %d\n" % row for row in rows)


def _history(c):
    sku = ascii_upper(c.positionals[0])
    if sku not in c.catalog:
        raise Failure("unknown SKU %s" % sku)
    rows = history(c.moves, sku)
    if c.options.get("json"):
        return _dump(
            [
                {
                    "date": m.date.isoformat(),
                    "delta": "%+d" % m.quantity,
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in rows
            ]
        )
    return "".join(
        "%s %+d %d%s\n" % (m.date.isoformat(), m.quantity, balance, " " + m.note if m.note else "")
        for m, balance in rows
    )


def _movement(c):
    date_text, sku, qty_text = c.positionals[:3]
    note = (c.positionals[3] if len(c.positionals) > 3 else "").strip(" \t")
    sku = ascii_upper(sku)
    if sku not in c.catalog:
        raise Failure("unknown SKU %s" % sku)
    if not _UINT.fullmatch(qty_text) or int(qty_text) < 1:
        raise Failure("bad quantity %r (a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise Failure("a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise Failure("the note is not valid UTF-8")
    quantity = int(qty_text) * (1 if c.command == "receive" else -1)
    parts = c.moves_text.split("\n")
    line = len(parts) if c.moves_text.endswith("\n") else len(parts) + 1
    candidate = Movement(parse_date(date_text), sku, quantity, note, line)
    bad = first_below_zero(c.moves + [candidate])
    if bad is not None:
        where = "this movement" if bad is candidate else "the movement on line %d" % bad.line
        raise Failure("refused: stock of %s would go below zero at %s" % (bad.sku, where))
    _append(c.directory, c.moves_data, [candidate])
    return _move_text(candidate) + "\n"


def _quote(c):
    order = _find_order(c.orders, c.positionals[0])
    return _render_quote(order, price_order(order, c.catalog), "", c.options.get("json"))


def _fulfil(c):
    order = _find_order(c.orders, c.positionals[0])
    date = parse_date(c.positionals[1])
    if date < order.date:
        raise Failure("refused: %s is dated %s, before the order" % (date, order.date))
    rows = order_rows(order, shipped_index(c.moves))
    added = []
    for sku, quantity, done in rows:
        ship = max(0, min(quantity - done, available_to_ship(c.moves, sku, date)))
        if ship:
            added.append(Movement(date, sku, -ship, "order " + order.id, 0))
    if added:
        _append(c.directory, c.moves_data, added)
    after = order_rows(order, shipped_index(c.moves + added))
    sent = {m.sku: -m.quantity for m in added}
    out = [
        "%s shipped %d backordered %d" % (sku, sent.get(sku, 0), quantity - done)
        for sku, quantity, done in after
    ]
    out.append("status " + order_status(after))
    return "\n".join(out) + "\n"


def _invoice(c):
    order = _find_order(c.orders, c.positionals[0])
    rows = order_rows(order, shipped_index(c.moves))
    quote = _invoice_quote(order, rows, c.catalog)
    if quote is None:
        raise Failure("refused: nothing has shipped for %s" % order.id)
    return _render_quote(order, quote, "invoice ", c.options.get("json"))


def _report(c):
    index = shipped_index(c.moves)
    ordered = sorted(
        c.orders, key=lambda o: (o.date, int(o.id[3:]), o.id)
    )
    rows = []
    for order in ordered:
        lines = order_rows(order, index)
        invoice = _invoice_quote(order, lines, c.catalog)
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(lines),
                "ordered": sum(q for _, q, _ in lines),
                "shipped": sum(s for _, _, s in lines),
                "quoted": _amount(price_order(order, c.catalog).total),
                "invoiced": _amount(invoice.total) if invoice else "0.00",
            }
        )
    fmt = c.options.get("format", "text")
    if fmt == "json":
        return _dump(rows)
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"])
        for r in rows:
            writer.writerow(
                [r["order"], r["date"], r["customer"], r["status"], r["ordered"], r["shipped"], r["quoted"], r["invoiced"]]
            )
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n"
        % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


HANDLERS = {
    "stock": _stock,
    "low": _low,
    "history": _history,
    "receive": _movement,
    "ship": _movement,
    "quote": _quote,
    "fulfil": _fulfil,
    "invoice": _invoice,
    "report": _report,
}


def run(command, positionals, options):
    """Read and parse the files the command needs, carry it out, return its output."""
    directory = options.get("dir", ".")
    if not os.path.isdir(directory):
        raise InputError("%s: not a folder that can be read" % directory)
    needed = FILES[command]
    raw = {name: _read(directory, name, name == "catalog") for name in needed}
    catalog = _parse("catalog.txt", parse_catalog, raw["catalog"][1])
    c = SimpleNamespace(
        command=command,
        positionals=positionals,
        options=options,
        directory=directory,
        catalog=catalog,
        moves=[],
        moves_data=b"",
        moves_text="",
        orders=[],
    )
    if "movements" in raw:
        c.moves_data, c.moves_text = raw["movements"]
        c.moves = _parse("movements.txt", parse_movements, c.moves_text, catalog)
    if "orders" in raw:
        c.orders = _parse("orders.txt", parse_orders, raw["orders"][1], catalog)
    return HANDLERS[command](c)


def _write_stderr(message):
    stream = sys.stderr
    try:
        stream.write(message + "\n")
    except UnicodeEncodeError:
        stream.write(message.encode("utf-8", "backslashreplace").decode("ascii", "replace") + "\n")
    try:
