)


class Bytes(io.TextIOWrapper):
    """A text stream over bytes, like a real stdout."""

    def __init__(self):
        super().__init__(io.BytesIO(), encoding="ascii", errors="strict", newline="")

    def raw(self):
        self.flush()
        return self.buffer.getvalue()


def call(argv, stdout=None):
    """Run cli.main in-process; return (exit code, stdout text, stderr text)."""
    out = stdout or io.StringIO()
    err = io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = cli.main(list(argv))
    return code, out.getvalue() if hasattr(out, "getvalue") else None, err.getvalue()


class ShopTest(unittest.TestCase):
